const jobTitle = $json.jobTitle || "";
const industry = $json.industry || "";
const location = $json.location || "";
const searchQuery = `site:linkedin.com/in/ ${jobTitle} ${industry} ${location}`;
return [{ json: { query: searchQuery } }];

const results = $json.items || [];

return results.map(item => {
  const title = item.title || "";
  const parts = title.split(" - ");

  const nom = parts[0]?.trim() || ""; // extrait juste le nom
  const titreProfil = title;          // garde tout le titre original

  return {
    json: {
      "Nom": nom,
      "Titre du profil": titreProfil,
      "Email": "",
      "Téléphone": "",
      "LienCV": "",
      "Source": "LinkedIn via Google",
      "LienProfil": item.link || ""
    }
  };
});

