const submittedAt = new Date($json.submittedAt);  // Date de soumission
const desiredDate = new Date($input.first().json['Date de   Rendez-vous Soufaité ?']); // Date souhaitée

const differenceInDays = (desiredDate - submittedAt) / (1000 * 3600 * 24); // Calcul de la différence en jours

if (desiredDate < submittedAt) {
    return { "error": "La date de rendez-vous souhaitée est déjà passée." };
} else if (differenceInDays <= 3) {
    return { "error": "La date de rendez-vous est trop proche." };
} else {
    return { "error": null, "validDate": true };
}
